{
  "project_purpose": "glom is a Python library for querying, transforming, validating, and restructuring nested data structures declaratively. It provides deep path-based navigation, pattern matching, stream processing, in-place mutations, and a command-line interface for manipulating complex Python objects and data formats.",
  "features": [
    {
      "name": "Core Declarative Data Transformation and Path Access",
      "definition": "Extract and transform nested data using declarative specifications, deep path navigators, target-relative expressions (T), and control flow specifiers such as Coalesce, Call, Invoke, Ref, Val, and Spec.",
      "files": [
        "glom/__init__.py",
        "glom/core.py"
      ]
    },
    {
      "name": "Pattern Matching and Structural Validation",
      "definition": "Validate and assert target data structures, route values, and perform conditional transformations using Match, Check, Switch, Regex, and boolean combinators like And, Or, and Not.",
      "files": [
        "glom/__init__.py",
        "glom/matching.py"
      ]
    },
    {
      "name": "In-Place Target Mutation and Deletion",
      "definition": "Perform deep assignment, value updates, and deep key/attribute deletion operations across complex nested target structures based on glom paths.",
      "files": [
        "glom/__init__.py",
        "glom/mutation.py"
      ]
    },
    {
      "name": "Data Reduction, Aggregation, and Grouping",
      "definition": "Aggregate, fold, sum, count, flatten, bucket, and group iterable target data using specifiers such as Fold, Flatten, Group, and built-in accumulators (First, Avg, Max, Min, Sample).",
      "files": [
        "glom/__init__.py",
        "glom/grouping.py",
        "glom/reduction.py"
      ]
    },
    {
      "name": "Lazy Streaming and Pipeline Processing",
      "definition": "Construct lazy iterable transformation pipelines with the Iter specifier, supporting operations like map, filter, chunked, windowed, split, unique, slice, takewhile, and dropwhile.",
      "files": [
        "glom/streaming.py"
      ]
    },
    {
      "name": "Command-Line Interface",
      "definition": "Run glom transformations directly from the terminal against files or standard input across JSON, YAML, TOML, and Python formats using command-line arguments and flags.",
      "files": [
        "glom/__main__.py",
        "glom/cli.py"
      ]
    },
    {
      "name": "Interactive Tutorial and Sample Models",
      "definition": "Provides built-in tutorial data structures, sample models (Contact, Email), and in-memory persistence managers for interactive learning and demonstrations.",
      "files": [
        "glom/tutorial.py"
      ]
    }
  ]
}
